# Batch 2 — mantra collections (Vedic / Puranic, public domain). Meanings original.
M = "mantra"

OM_NAMAH_SHIVAY = [
 (M,"पंचाक्षर मंत्र\nॐ नमः शिवाय॥","‘मैं शिव को नमन करता हूँ।’ यह शिव का पंचाक्षर (पाँच अक्षरों वाला) मंत्र है — न, मः, शि, वा, य। यजुर्वेद के श्री रुद्रम् में आने वाला यह मंत्र शिव-भक्ति का सबसे सरल और प्रमुख मंत्र है; इसे कोई भी, कभी भी जप सकता है।"),
 (M,"शिव ध्यान मंत्र\nकर्पूरगौरं करुणावतारं\nसंसारसारं भुजगेन्द्रहारम्।\nसदा वसन्तं हृदयारविन्दे\nभवं भवानीसहितं नमामि॥","कपूर जैसे गोरे, करुणा के अवतार, संसार के सार, सर्पराज का हार पहनने वाले, जो सदा हृदय-कमल में बसते हैं — उन भव (शिव) को भवानी सहित मैं नमन करता हूँ। (यह श्लोक आरती के बाद बोला जाता है।)"),
 (M,"शिव गायत्री मंत्र\nॐ तत्पुरुषाय विद्महे महादेवाय धीमहि।\nतन्नो रुद्रः प्रचोदयात्॥","हम उस परम पुरुष को जानें, महादेव का ध्यान करें; वे रुद्र हमारी बुद्धि को प्रेरित करें।"),
 (M,"शिव आराधना मंत्र\nॐ नमो भगवते रुद्राय॥","भगवान रुद्र को नमस्कार।"),
 (M,"क्षमा प्रार्थना\nकरचरणकृतं वाक्कायजं कर्मजं वा\nश्रवणनयनजं वा मानसं वापराधम्।\nविहितमविहितं वा सर्वमेतत्क्षमस्व\nजय जय करुणाब्धे श्रीमहादेव शम्भो॥","हाथ-पैर से, वाणी या शरीर से, कर्मों से, कानों-आँखों से या मन से जो भी अपराध हुए हों — जाने या अनजाने — हे करुणा के सागर महादेव शंभु, सबको क्षमा कीजिए। (पूजा के अंत में)"),
]

PRATAH_MANTRA = [
 (M,"उठते ही — हथेली दर्शन\nकराग्रे वसते लक्ष्मीः करमध्ये सरस्वती।\nकरमूले तु गोविन्दः प्रभाते करदर्शनम्॥","हाथ के आगे के भाग में लक्ष्मी, बीच में सरस्वती और जड़ में गोविंद बसते हैं; इसलिए सुबह उठते ही अपनी हथेलियाँ देखनी चाहिए।"),
 (M,"धरती पर पैर रखने से पहले — भूमि वंदना\nसमुद्रवसने देवि पर्वतस्तनमण्डिते।\nविष्णुपत्नि नमस्तुभ्यं पादस्पर्शं क्षमस्व मे॥","हे समुद्र रूपी वस्त्र वाली, पर्वतों से सजी, विष्णु की पत्नी धरती माँ, आपको नमस्कार; मेरे पैरों के स्पर्श को क्षमा कीजिए।"),
 (M,"स्नान करते समय\nगङ्गे च यमुने चैव गोदावरि सरस्वति।\nनर्मदे सिन्धु कावेरि जलेऽस्मिन् सन्निधिं कुरु॥","हे गंगा, यमुना, गोदावरी, सरस्वती, नर्मदा, सिंधु और कावेरी, इस जल में आप सब पधारिए। (नहाने का पानी पवित्र हो)"),
 (M,"सूर्य को अर्घ्य देते समय\nॐ घृणि सूर्याय नमः॥\nएहि सूर्य सहस्रांशो तेजोराशे जगत्पते।\nअनुकम्पय मां भक्त्या गृहाणार्घ्यं दिवाकर॥","हे हज़ार किरणों वाले, तेज के भंडार, जगत के स्वामी सूर्यदेव, आइए; मुझ पर कृपा कीजिए और भक्ति से दिया यह अर्घ्य स्वीकार कीजिए।"),
 (M,"दीपक जलाते समय\nशुभं करोति कल्याणमारोग्यं धनसम्पदा।\nशत्रुबुद्धिविनाशाय दीपज्योतिर्नमोऽस्तु ते॥","जो शुभ करती है, कल्याण, आरोग्य और धन-संपदा देती है, शत्रुता की बुद्धि का नाश करती है — हे दीप-ज्योति, आपको नमस्कार।"),
 (M,"गुरु वंदना\nगुरुर्ब्रह्मा गुरुर्विष्णुर्गुरुर्देवो महेश्वरः।\nगुरुः साक्षात् परब्रह्म तस्मै श्रीगुरवे नमः॥","गुरु ही ब्रह्मा, गुरु ही विष्णु और गुरु ही महेश्वर हैं; गुरु साक्षात परब्रह्म हैं — ऐसे श्री गुरु को नमस्कार।"),
 (M,"समर्पण\nत्वमेव माता च पिता त्वमेव\nत्वमेव बन्धुश्च सखा त्वमेव।\nत्वमेव विद्या द्रविणं त्वमेव\nत्वमेव सर्वं मम देव देव॥","हे देवों के देव, आप ही मेरी माता, पिता, भाई और मित्र हैं; आप ही विद्या और धन हैं; आप ही मेरा सब कुछ हैं।"),
]

GAYATRI_SANGRAH = [
 (M,"गणेश गायत्री\nॐ एकदन्ताय विद्महे वक्रतुण्डाय धीमहि।\nतन्नो दन्ती प्रचोदयात्॥","हम एकदंत को जानें, वक्रतुंड का ध्यान करें; वे दंती (गणेश) हमारी बुद्धि को प्रेरित करें।"),
 (M,"शिव गायत्री\nॐ तत्पुरुषाय विद्महे महादेवाय धीमहि।\nतन्नो रुद्रः प्रचोदयात्॥","हम परम पुरुष को जानें, महादेव का ध्यान करें; वे रुद्र हमारी बुद्धि को प्रेरित करें।"),
 (M,"विष्णु गायत्री\nॐ नारायणाय विद्महे वासुदेवाय धीमहि।\nतन्नो विष्णुः प्रचोदयात्॥","हम नारायण को जानें, वासुदेव का ध्यान करें; वे विष्णु हमारी बुद्धि को प्रेरित करें।"),
 (M,"लक्ष्मी गायत्री\nॐ महालक्ष्म्यै च विद्महे विष्णुपत्न्यै च धीमहि।\nतन्नो लक्ष्मीः प्रचोदयात्॥","हम महालक्ष्मी को जानें, विष्णु-पत्नी का ध्यान करें; वे लक्ष्मी हमें प्रेरित करें।"),
 (M,"दुर्गा गायत्री\nॐ कात्यायन्यै च विद्महे कन्याकुमार्यै धीमहि।\nतन्नो दुर्गिः प्रचोदयात्॥","हम कात्यायनी को जानें, कन्याकुमारी का ध्यान करें; वे दुर्गा हमें प्रेरित करें।"),
 (M,"सरस्वती गायत्री\nॐ वाग्देव्यै च विद्महे विरिञ्चिपत्न्यै च धीमहि।\nतन्नो वाणी प्रचोदयात्॥","हम वाणी की देवी को जानें, ब्रह्मा की पत्नी का ध्यान करें; वे सरस्वती हमें प्रेरित करें।"),
 (M,"हनुमान गायत्री\nॐ आञ्जनेयाय विद्महे वायुपुत्राय धीमहि।\nतन्नो हनुमत् प्रचोदयात्॥","हम अंजनी-पुत्र को जानें, वायुपुत्र का ध्यान करें; वे हनुमान हमें प्रेरित करें।"),
 (M,"कृष्ण गायत्री\nॐ देवकीनन्दनाय विद्महे वासुदेवाय धीमहि।\nतन्नो कृष्णः प्रचोदयात्॥","हम देवकीनंदन को जानें, वासुदेव का ध्यान करें; वे कृष्ण हमें प्रेरित करें।"),
 (M,"राम गायत्री\nॐ दाशरथये विद्महे सीतावल्लभाय धीमहि।\nतन्नो रामः प्रचोदयात्॥","हम दशरथ-पुत्र को जानें, सीता-पति का ध्यान करें; वे राम हमें प्रेरित करें।"),
 (M,"सूर्य गायत्री\nॐ भास्कराय विद्महे महाद्युतिकराय धीमहि।\nतन्नो आदित्यः प्रचोदयात्॥","हम भास्कर को जानें, महान प्रकाश देने वाले का ध्यान करें; वे आदित्य हमें प्रेरित करें।"),
 (M,"शनि गायत्री\nॐ काकध्वजाय विद्महे खड्गहस्ताय धीमहि।\nतन्नो मन्दः प्रचोदयात्॥","हम कौए की ध्वजा वाले को जानें, हाथ में तलवार वाले का ध्यान करें; वे शनि हमें प्रेरित करें।"),
]

NAVGRAH_MANTRA = [
 (M,"नवग्रह स्तुति\nब्रह्मा मुरारिस्त्रिपुरान्तकारी\nभानुः शशी भूमिसुतो बुधश्च।\nगुरुश्च शुक्रः शनिराहुकेतवः\nसर्वे ग्रहाः शान्तिकरा भवन्तु॥","ब्रह्मा, विष्णु, शिव, सूर्य, चंद्र, मंगल, बुध, गुरु, शुक्र, शनि, राहु और केतु — सभी ग्रह शांति देने वाले हों।"),
 (M,"सूर्य बीज मंत्र (रविवार)\nॐ ह्रां ह्रीं ह्रौं सः सूर्याय नमः॥","सूर्यदेव को नमस्कार — आत्मविश्वास, सम्मान और स्वास्थ्य के लिए।"),
 (M,"चंद्र बीज मंत्र (सोमवार)\nॐ श्रां श्रीं श्रौं सः चन्द्रमसे नमः॥","चंद्रदेव को नमस्कार — मन की शांति के लिए।"),
 (M,"मंगल बीज मंत्र (मंगलवार)\nॐ क्रां क्रीं क्रौं सः भौमाय नमः॥","भूमि-पुत्र मंगल को नमस्कार — साहस और ऊर्जा के लिए।"),
 (M,"बुध बीज मंत्र (बुधवार)\nॐ ब्रां ब्रीं ब्रौं सः बुधाय नमः॥","बुध को नमस्कार — बुद्धि और वाणी के लिए।"),
 (M,"गुरु (बृहस्पति) बीज मंत्र (गुरुवार)\nॐ ग्रां ग्रीं ग्रौं सः गुरवे नमः॥","देवगुरु बृहस्पति को नमस्कार — ज्ञान और सौभाग्य के लिए।"),
 (M,"शुक्र बीज मंत्र (शुक्रवार)\nॐ द्रां द्रीं द्रौं सः शुक्राय नमः॥","शुक्र को नमस्कार — सुख-सुविधा और प्रेम के लिए।"),
 (M,"शनि बीज मंत्र (शनिवार)\nॐ प्रां प्रीं प्रौं सः शनैश्चराय नमः॥\nनीलाञ्जनसमाभासं रविपुत्रं यमाग्रजम्।\nछायामार्तण्डसम्भूतं तं नमामि शनैश्चरम्॥","शनिदेव को नमस्कार। जो नीले काजल जैसी आभा वाले, सूर्य के पुत्र, यम के बड़े भाई और छाया-सूर्य से उत्पन्न हैं, उन शनैश्चर को मैं प्रणाम करता हूँ।"),
 (M,"राहु बीज मंत्र\nॐ भ्रां भ्रीं भ्रौं सः राहवे नमः॥","राहु को नमस्कार — अचानक आने वाली बाधाओं की शांति के लिए।"),
 (M,"केतु बीज मंत्र\nॐ स्रां स्रीं स्रौं सः केतवे नमः॥","केतु को नमस्कार — आध्यात्मिक उन्नति और बाधा-शांति के लिए।"),
]

SURYA_12_NAAM = [
 (M,"सूर्य के 12 नाम (सूर्य नमस्कार मंत्र)\nॐ मित्राय नमः। ॐ रवये नमः।\nॐ सूर्याय नमः। ॐ भानवे नमः।\nॐ खगाय नमः। ॐ पूष्णे नमः।\nॐ हिरण्यगर्भाय नमः। ॐ मरीचये नमः।\nॐ आदित्याय नमः। ॐ सवित्रे नमः।\nॐ अर्काय नमः। ॐ भास्कराय नमः॥","सबके मित्र, चमकने वाले, कर्म की प्रेरणा देने वाले, प्रकाश देने वाले, आकाश में चलने वाले, पोषण करने वाले, सृष्टि का स्वर्णिम गर्भ, किरणों वाले, अदिति के पुत्र, जीवन देने वाले, पूजनीय और प्रकाश फैलाने वाले सूर्य को नमस्कार। सूर्य नमस्कार के बारह चक्रों में एक-एक नाम बोला जाता है।"),
 (M,"अर्घ्य मंत्र\nएहि सूर्य सहस्रांशो तेजोराशे जगत्पते।\nअनुकम्पय मां भक्त्या गृहाणार्घ्यं दिवाकर॥","हे हज़ार किरणों वाले, तेज के भंडार, जगत के स्वामी सूर्यदेव, आइए; मुझ पर कृपा कीजिए और भक्ति से दिया यह अर्घ्य स्वीकार कीजिए।"),
 (M,"सूर्य गायत्री\nॐ भास्कराय विद्महे महाद्युतिकराय धीमहि।\nतन्नो आदित्यः प्रचोदयात्॥","हम भास्कर को जानें, महान प्रकाश देने वाले का ध्यान करें; वे आदित्य हमें प्रेरित करें।"),
]

BHOJAN_SHAYAN = [
 (M,"भोजन से पहले (गीता 4.24)\nब्रह्मार्पणं ब्रह्म हविर्ब्रह्माग्नौ ब्रह्मणा हुतम्।\nब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना॥","अर्पण करने का साधन ब्रह्म है, भोजन ब्रह्म है, अग्नि (भूख) ब्रह्म है और अर्पण करने वाला भी ब्रह्म है; जो हर कर्म में ब्रह्म को देखता है, वह ब्रह्म को ही पाता है।"),
 (M,"अन्नपूर्णा मंत्र\nअन्नपूर्णे सदापूर्णे शङ्करप्राणवल्लभे।\nज्ञानवैराग्यसिद्ध्यर्थं भिक्षां देहि च पार्वति॥","हे सदा भरपूर रहने वाली, शंकर की प्राणप्रिया माँ अन्नपूर्णा पार्वती, ज्ञान और वैराग्य की सिद्धि के लिए मुझे भिक्षा (अन्न) दीजिए।"),
 (M,"साथ भोजन करते समय — सह नाववतु\nॐ सह नाववतु। सह नौ भुनक्तु।\nसह वीर्यं करवावहै।\nतेजस्वि नावधीतमस्तु मा विद्विषावहै॥\nॐ शान्तिः शान्तिः शान्तिः॥","परमात्मा हम दोनों की साथ रक्षा करें, साथ पोषण करें; हम साथ मिलकर शक्ति पाएँ; हमारा पढ़ा हुआ तेजस्वी हो; हम आपस में द्वेष न करें। ॐ शांति, शांति, शांति। (कठोपनिषद्)"),
 (M,"सोने से पहले — बुरे सपनों से रक्षा\nरामं स्कन्दं हनूमन्तं वैनतेयं वृकोदरम्।\nशयने यः स्मरेन्नित्यं दुःस्वप्नं तस्य नश्यति॥","जो रोज़ सोते समय राम, स्कंद (कार्तिकेय), हनुमान, गरुड़ और भीम का स्मरण करता है, उसके बुरे सपने नष्ट हो जाते हैं।"),
 (M,"दिन भर की भूलों की क्षमा\nकरचरणकृतं वाक्कायजं कर्मजं वा\nश्रवणनयनजं वा मानसं वापराधम्।\nविहितमविहितं वा सर्वमेतत्क्षमस्व\nजय जय करुणाब्धे श्रीमहादेव शम्भो॥","हाथ-पैर, वाणी, शरीर, कर्म, कान, आँख या मन से जाने-अनजाने जो भी अपराध हुए हों, हे करुणा के सागर महादेव, सबको क्षमा कीजिए।"),
]

KRISHNA_MANTRA = [
 (M,"हरे कृष्ण महामंत्र\nहरे राम हरे राम राम राम हरे हरे।\nहरे कृष्ण हरे कृष्ण कृष्ण कृष्ण हरे हरे॥","सोलह नामों वाला यह महामंत्र कलि-संतरण उपनिषद् में कलियुग के लिए सबसे श्रेष्ठ बताया गया है। ‘हरे’ भगवान की आह्लादिनी शक्ति (राधा) का संबोधन है, और राम व कृष्ण भगवान के नाम हैं — इसमें भगवान से उनकी सेवा में लगाने की पुकार है।"),
 (M,"वासुदेव द्वादशाक्षर मंत्र\nॐ नमो भगवते वासुदेवाय॥","भगवान वासुदेव (श्रीकृष्ण/विष्णु) को नमस्कार। बारह अक्षरों वाला यह मंत्र ध्रुव जी ने जपा था।"),
 (M,"क्लेश नाशक कृष्ण मंत्र\nकृष्णाय वासुदेवाय हरये परमात्मने।\nप्रणतः क्लेशनाशाय गोविन्दाय नमो नमः॥","कृष्ण, वासुदेव, हरि, परमात्मा, शरणागत के क्लेश मिटाने वाले गोविंद को बार-बार नमस्कार। (श्रीमद्भागवत)"),
 (M,"श्रीकृष्ण शरणं मम\nश्रीकृष्णः शरणं मम॥","श्रीकृष्ण ही मेरी शरण हैं — पुष्टिमार्ग (वल्लभ संप्रदाय) का अष्टाक्षर मंत्र।"),
 (M,"कृष्ण वंदना\nवसुदेवसुतं देवं कंसचाणूरमर्दनम्।\nदेवकीपरमानन्दं कृष्णं वन्दे जगद्गुरुम्॥","वसुदेव के पुत्र, कंस और चाणूर का नाश करने वाले, देवकी के परम आनंद, जगद्गुरु श्रीकृष्ण को मैं नमन करता हूँ।"),
]

DURGA_MANTRA = [
 (M,"नवार्ण मंत्र\nॐ ऐं ह्रीं क्लीं चामुण्डायै विच्चे॥","नौ अक्षरों वाला यह मंत्र दुर्गा सप्तशती का मूल मंत्र है — ‘ऐं’ सरस्वती, ‘ह्रीं’ महालक्ष्मी और ‘क्लीं’ महाकाली का बीज है; चामुंडा देवी से अज्ञान के बंधन काटने की प्रार्थना है। नवरात्रि में इसका जाप विशेष होता है।"),
 (M,"सर्वमंगल मांगल्ये\nसर्वमङ्गलमाङ्गल्ये शिवे सर्वार्थसाधिके।\nशरण्ये त्र्यम्बके गौरि नारायणि नमोऽस्तु ते॥","हे सब मंगलों का मंगल करने वाली, कल्याणी, सब काम सिद्ध करने वाली, शरण देने वाली, तीन नेत्रों वाली गौरी नारायणी, आपको नमस्कार।"),
 (M,"जयन्ती मंगला काली\nॐ जयन्ती मङ्गला काली भद्रकाली कपालिनी।\nदुर्गा क्षमा शिवा धात्री स्वाहा स्वधा नमोऽस्तु ते॥","जयंती, मंगला, काली, भद्रकाली, कपालिनी, दुर्गा, क्षमा, शिवा, धात्री, स्वाहा और स्वधा — इन रूपों वाली देवी, आपको नमस्कार। (अर्गला स्तोत्र)"),
 (M,"या देवी — शक्ति रूप\nया देवी सर्वभूतेषु शक्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","जो देवी सब प्राणियों में शक्ति के रूप में बसती हैं, उन्हें बार-बार नमस्कार।"),
 (M,"या देवी — माँ रूप\nया देवी सर्वभूतेषु मातृरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","जो देवी सब प्राणियों में माँ के रूप में बसती हैं, उन्हें बार-बार नमस्कार।"),
 (M,"या देवी — लक्ष्मी रूप\nया देवी सर्वभूतेषु लक्ष्मीरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","जो देवी सब प्राणियों में लक्ष्मी (समृद्धि) के रूप में बसती हैं, उन्हें बार-बार नमस्कार।"),
 (M,"या देवी — बुद्धि रूप\nया देवी सर्वभूतेषु बुद्धिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","जो देवी सब प्राणियों में बुद्धि के रूप में बसती हैं, उन्हें बार-बार नमस्कार।"),
 (M,"या देवी — शांति रूप\nया देवी सर्वभूतेषु शान्तिरूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","जो देवी सब प्राणियों में शांति के रूप में बसती हैं, उन्हें बार-बार नमस्कार।"),
 (M,"या देवी — श्रद्धा रूप\nया देवी सर्वभूतेषु श्रद्धारूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","जो देवी सब प्राणियों में श्रद्धा के रूप में बसती हैं, उन्हें बार-बार नमस्कार।"),
 (M,"या देवी — दया रूप\nया देवी सर्वभूतेषु दयारूपेण संस्थिता।\nनमस्तस्यै नमस्तस्यै नमस्तस्यै नमो नमः॥","जो देवी सब प्राणियों में दया के रूप में बसती हैं, उन्हें बार-बार नमस्कार।"),
]

SHANTI_MANTRA = [
 (M,"ॐ पूर्णमदः (ईशावास्य उपनिषद्)\nॐ पूर्णमदः पूर्णमिदं पूर्णात्पूर्णमुदच्यते।\nपूर्णस्य पूर्णमादाय पूर्णमेवावशिष्यते॥\nॐ शान्तिः शान्तिः शान्तिः॥","वह (परमात्मा) पूर्ण है, यह (जगत) भी पूर्ण है; पूर्ण से ही पूर्ण उत्पन्न होता है। पूर्ण में से पूर्ण निकाल लेने पर भी पूर्ण ही बचता है। ॐ शांति, शांति, शांति।"),
 (M,"असतो मा सद्गमय (बृहदारण्यक उपनिषद्)\nॐ असतो मा सद्गमय।\nतमसो मा ज्योतिर्गमय।\nमृत्योर्मा अमृतं गमय।\nॐ शान्तिः शान्तिः शान्तिः॥","हे प्रभु, मुझे असत्य से सत्य की ओर, अंधकार से प्रकाश की ओर, और मृत्यु से अमरता की ओर ले चलो।"),
 (M,"द्यौः शान्ति (यजुर्वेद 36.17)\nॐ द्यौः शान्तिरन्तरिक्षं शान्तिः\nपृथिवी शान्तिरापः शान्तिरोषधयः शान्तिः।\nवनस्पतयः शान्तिर्विश्वेदेवाः शान्तिर्ब्रह्म शान्तिः\nसर्वं शान्तिः शान्तिरेव शान्तिः सा मा शान्तिरेधि॥\nॐ शान्तिः शान्तिः शान्तिः॥","आकाश, अंतरिक्ष, पृथ्वी, जल, औषधियाँ, वनस्पतियाँ, सब देवता और ब्रह्म — सब में शांति हो; सब कुछ शांत हो, और वह शांति मुझे भी मिले।"),
 (M,"सर्वे भवन्तु सुखिनः\nॐ सर्वे भवन्तु सुखिनः सर्वे सन्तु निरामयाः।\nसर्वे भद्राणि पश्यन्तु मा कश्चिद्दुःखभाग्भवेत्॥\nॐ शान्तिः शान्तिः शान्तिः॥","सब सुखी हों, सब रोगमुक्त हों, सब शुभ देखें, कोई भी दुखी न हो।"),
 (M,"सह नाववतु (कठोपनिषद्)\nॐ सह नाववतु। सह नौ भुनक्तु।\nसह वीर्यं करवावहै।\nतेजस्वि नावधीतमस्तु मा विद्विषावहै॥\nॐ शान्तिः शान्तिः शान्तिः॥","परमात्मा हम (गुरु-शिष्य) दोनों की रक्षा करें, साथ पोषण करें, हम साथ शक्ति पाएँ, हमारी विद्या तेजस्वी हो और हम आपस में द्वेष न करें।"),
]
